-- Table client_geo : une position (latitude, longitude) pour chacun des 99 441
-- customer_id du fichier olist_customers_dataset.csv (jeu Olist, Kaggle).
-- Coordonnées inventées mais cohérentes avec la colonne customer_city : centre de
-- la commune (référentiel officiel IBGE des municipalités brésiliennes), plus un
-- léger décalage aléatoire de 1 à 8 km selon la taille de la ville.
SET client_encoding = 'UTF8';
CREATE TABLE client_geo (
    customer_id  VARCHAR(32)  PRIMARY KEY,
    latitude     NUMERIC(9,6) NOT NULL CHECK (latitude  BETWEEN -34 AND 6),
    longitude    NUMERIC(9,6) NOT NULL CHECK (longitude BETWEEN -74 AND -34)
);
ANALYZE client_geo;
